<?php
namespace App\Filament\Resources\Staff;
use App\Filament\Resources\Concerns\AdminResource; use App\Filament\Resources\Staff\Pages\ManageStaff; use App\Models\User;
use BackedEnum; use Filament\Actions\EditAction; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder;
class StaffResource extends AdminResource {protected static ?string $model=User::class;protected static string $viewPermission='staff.manage';protected static ?string $managePermission='staff.manage';protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedUserGroup;protected static ?string $navigationLabel='Nhân viên';protected static string|\UnitEnum|null $navigationGroup='Hệ thống';protected static ?int $navigationSort=10;public static function getEloquentQuery():Builder{return parent::getEloquentQuery()->whereHas('roles',fn($q)=>$q->where('is_staff',true))->with('roles');}public static function form(Schema $s):Schema{return $s->components([TextInput::make('name')->label('Họ tên')->required(),TextInput::make('email')->label('Email')->email()->required()->unique(ignoreRecord:true),TextInput::make('phone')->label('Điện thoại'),Select::make('status')->label('Trạng thái')->options(['active'=>'Hoạt động','blocked'=>'Đã khóa'])->required(),Select::make('roles')->relationship('roles','name')->multiple()->preload()->searchable()->label('Vai trò')->required()])->columns(2);}public static function table(Table $t):Table{return $t->columns([TextColumn::make('name')->label('Nhân viên')->searchable()->weight('bold'),TextColumn::make('email')->label('Email')->searchable(),TextColumn::make('roles.name')->label('Vai trò')->badge(),TextColumn::make('status')->label('Trạng thái')->badge(),TextColumn::make('updated_at')->label('Cập nhật')->dateTime('d/m/Y H:i')])->recordActions([EditAction::make()->label('Sửa')]);}public static function canCreate():bool{return false;}public static function canDelete(\Illuminate\Database\Eloquent\Model $r):bool{return false;}public static function getPages():array{return ['index'=>ManageStaff::route('/')];}}
